/**
 * Credits of Island of Settlers: the creator and every third-party asset, tool and library that
 * ships with the game. The single source of the in-game Credits window and of CREDITS.md
 * (regenerated by `npm run credits`; tests/credits.test.ts fails when the two drift).
 * Provenance notes per asset: docs/reference/asset-credits.md and each assets/models/** LICENSE.txt.
 */

export type CreditLicenceId =
  | "apache-2.0"
  | "cc-by-4.0"
  | "cc0-1.0"
  | "gpl-3.0"
  | "mit"
  | "nasa-media"
  | "original"
  | "owner"
  | "system";

export interface CreditLicence {
  /** Short name shown on the licence badge. */
  name: string;
  /** Licence text; absent for original, owner-owned and system items. */
  url?: string;
}

export interface CreditEntry {
  author: string;
  authorUrl?: string;
  /** Required for CC BY: what was changed from the source. */
  changes?: string;
  licence: CreditLicenceId;
  /** Tool the owner made an owner-owned asset with, shown with the licence: "Owner-owned (Tripo3D)". */
  madeWith?: string;
  sourceUrl?: string;
  title: string;
  /** Where the asset or tool appears in the game. */
  usedFor: string;
}

export interface CreditCategory {
  entries: readonly CreditEntry[];
  id: string;
  /** One line under the heading. */
  note?: string;
  title: string;
}

