/** CC BY needs the author, title, source, licence and changes credited where players see it. */
export const requiresAttribution = (entry: CreditEntry) => entry.licence === "cc-by-4.0";

/**
 * The licence line of an entry; original work reads "original work for Island of Settlers", owner
 * assets name the tool they were made with ("Owner-owned (Tripo3D)").
 */
export const describeLicence = (entry: CreditEntry) => {
  if (entry.licence === "original") return ORIGINAL_WORK;
  const { name } = CREDIT_LICENCES[entry.licence];
  return entry.madeWith ? `${name} (${entry.madeWith})` : name;
};

/** Attribution text required by CC BY 4.0, e.g. `"Rabbit" by X (source), licensed under ...`. */
export const getAttributionText = (entry: CreditEntry) => {
  const licence = CREDIT_LICENCES[entry.licence];
  const changes = entry.changes ? ` Changes: ${entry.changes}.` : "";
  return `"${entry.title}" by ${entry.author} (${entry.sourceUrl}), licensed under ` +
    `${licence.name} (${licence.url}).${changes}`;
};
